"""Old vs new vs CPython over the percent grid, chunked so it costs ~3 processes
per 200 cells instead of 3 per cell. A chunk that refuses is split in half until
the refusing cells are isolated, which bounds the process count."""
import subprocess, sys, collections
OLD="/tmp/lyp-gen"; NEW="/root/.lypning/bin/lypning"; CP="/usr/bin/python3"
CONVS = ['d','i','u','s','r','f','F','e','E','g','G','x','X','o','c']
FLAGS = ['', '-', '+', ' ', '#', '0', '-0', '+0', '# ', '-+', '0#', '+#']
WIDTHS = ['', '1', '5', '10']
PRECS  = ['', '.', '.0', '.2']
NUMS   = ['0','1','-1','42','-42','255','1.5','-1.5','True']
STRS   = ["''","'a'","'hello'"]

def prog(cells):
    L=["out=[]"]
    for spec, val in cells:
        L.append("try:\n    out.append(repr(%r %% (%s,)))\nexcept TypeError:\n    out.append('TypeError')\n"
                 "except ValueError:\n    out.append('ValueError')" % (spec, val))
    L.append("print('~'.join(out))")
    return "\n".join(L)

def run(binp, cells):
    p = subprocess.run([binp,"-c",prog(cells)],capture_output=True,text=True,timeout=120)
    if p.returncode != 0:
        return None
    return p.stdout.rstrip("\n").split('~')

def results(cells, depth=0):
    """[(spec,val,old,new,cpy)] with refusals marked, splitting on failure."""
    o, n, c = run(OLD, cells), run(NEW, cells), run(CP, cells)
    if o is not None and n is not None and c is not None and len(o)==len(n)==len(c)==len(cells):
        return list(zip([s for s,_ in cells], [v for _,v in cells], o, n, c))
    if len(cells) == 1:
        s, v = cells[0]
        return [(s, v, (o or ["REFUSED"])[0], (n or ["REFUSED"])[0], (c or ["ERR"])[0])]
    h = len(cells)//2
    return results(cells[:h], depth+1) + results(cells[h:], depth+1)

cells=[]
for cv in CONVS:
    pool = STRS if cv in ('s','r') else NUMS
    for fl in FLAGS:
        for w in WIDTHS:
            for pr in PRECS:
                for v in pool:
                    cells.append(('%'+fl+w+pr+cv, v))
print("grid: %d cells" % len(cells))
rows=[]
CH=200
for k in range(0, len(cells), CH):
    rows += results(cells[k:k+CH])
tally = collections.Counter(); ex = collections.defaultdict(list)
for spec, val, o, n, c in rows:
    if o == "REFUSED" or n == "REFUSED":
        tally["refused by one or both (fine)"] += 1
        if o != "REFUSED" and n == "REFUSED":
            tally["  ...NEWLY refused"] += 1; ex["NEWLY-REFUSED"].append((spec,val,o,n,c))
        continue
    om, nm = (o==c), (n==c)
    if om and nm: tally["both agree with CPython"] += 1
    elif nm: tally["FIXED"] += 1
    elif om:
        tally["BROKEN"] += 1; ex["BROKEN"].append((spec,val,o,n,c))
    elif o == n: tally["both wrong, unchanged"] += 1
    else:
        tally["both wrong, changed"] += 1; ex["CHANGED"].append((spec,val,o,n,c))
for k, v in tally.most_common(): print("  %6d  %s" % (v, k))
for k in ("BROKEN","NEWLY-REFUSED","CHANGED"):
    for spec,val,o,n,c in ex[k][:6]:
        print("\n  %s  %-12s %% %-6s   old=%-16r new=%-16r cpy=%r" % (k, spec, val, o, n, c))
sys.exit(1 if tally["BROKEN"] else 0)

