import json, ast
d=json.load(open('/home/user/lypning/.hillclimb/corpus.json'))
print("corpus entries loaded:", len(d), "(counted 2026-08-25)")

SETY=(ast.Set, ast.SetComp)
def is_sety(n):
    if isinstance(n, SETY): return True
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='set': return True
    if isinstance(n, ast.BinOp) and isinstance(n.op,(ast.BitAnd,ast.BitOr,ast.Sub,ast.BitXor)):
        return is_sety(n.left) or is_sety(n.right)
    return False

# map: name -> assigned a set?
def setnames(t):
    out=set()
    for n in ast.walk(t):
        if isinstance(n, ast.Assign) and is_sety(n.value):
            for tg in n.targets:
                if isinstance(tg, ast.Name): out.add(tg.id)
    return out

ORDER_SAFE={'sorted','len','sum','min','max','any','all','bool'}

hits=[]
for e in d:
    src=e.get('program') or ''
    try: t=ast.parse(src)
    except SyntaxError: continue
    names=setnames(t)
    def sety(n):
        return is_sety(n) or (isinstance(n, ast.Name) and n.id in names)
    hit=False; why=None
    for n in ast.walk(t):
        # print(<set>) directly, or an f-string/str/repr/join of a set
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in ('print','repr','str'):
            for a in n.args:
                if sety(a): hit=True; why='%s(<set>)'%n.func.id
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr=='join':
            if n.args and sety(n.args[0]): hit=True; why='join(<set>)'
        if isinstance(n, ast.FormattedValue) and sety(n.value):
            hit=True; why='f-string <set>'
        # iterating a set in a for-loop whose body prints
        if isinstance(n, ast.For) and sety(n.iter):
            if any(isinstance(x,ast.Call) and isinstance(x.func,ast.Name) and x.func.id=='print'
                   for x in ast.walk(n)):
                hit=True; why='for x in <set>: print'
    if hit: hits.append((e['id'], why, src))

print("\nPROGRAMS WHERE SET ORDER REACHES STDOUT:", len(hits))
for i,(eid,why,src) in enumerate(hits,1):
