helper = '''/// A case map that avoids the copy when there is nothing to change.
///
/// Two allocations become **none** for a receiver already in the case asked for,
/// which is not a corner: `line.lower()` over text that is already lowercase is
/// ordinary, and so is `.upper()` over a constant. When there IS something to
/// change, the ASCII path sizes the output exactly (an ASCII case map never
/// changes the byte length) and skips the Unicode case machinery.
///
/// `None` means "not ASCII, use the general path" — never "unchanged", which is
/// `Some(Value::Str(s.clone()))`. Collapsing those two would silently return the
/// receiver for a non-ASCII string that needed mapping.
#[inline]
fn ascii_cased(s: &Rc<str>, upper: bool) -> Option<Value> {
    if !s.is_ascii() {
        return None;
    }
    let changes = s.bytes().any(|b| {
        if upper {
            b.is_ascii_lowercase()
        } else {
            b.is_ascii_uppercase()
        }
    });
    if !changes {
        return Some(Value::Str(s.clone()));
    }
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        let c = if upper {
            b.to_ascii_uppercase()
        } else {
            b.to_ascii_lowercase()
        };
        out.push(c as char);
    }
    Some(Value::Str(out.into()))
}

/// `str::replace`, with the output sized before the first byte is written.
///
/// `std`'s starts from `String::new()` and grows: for a whole-file
/// `text.replace(old, new)` — the shape the corpus is full of, where the needle
/// is usually a multi-line block rather than one character — that is a dozen
/// reallocations and as many bytes copied again as the answer contains.
///
/// `None` means the needle does not occur, so the caller can return the receiver
/// and allocate nothing at all.
///
/// The empty needle is handled by the same loop rather than special-cased:
/// `match_indices("")` yields a zero-length match before every character and at
/// the end, so `'ab'.replace('', '-')` builds `-a-b-` exactly as CPython does.
fn replace_sized(s: &str, from: &str, to: &str, limit: Option<usize>) -> Option<String> {
    let mut hits = 0usize;
    for _ in s.match_indices(from) {
        if limit.is_some_and(|l| hits >= l) {
            break;
        }
        hits += 1;
    }
    if hits == 0 {
        return None;
    }
    // `hits * from.len() <= s.len()` because the matches do not overlap, so this
    // order of operations cannot underflow when `to` is shorter than `from`.
    let total = s.len() - hits * from.len() + hits * to.len();
    let mut out = String::with_capacity(total);
    let mut last = 0usize;
    let mut done = 0usize;
    for (start, part) in s.match_indices(from) {
        if done == hits {
            break;
        }
        out.push_str(&s[last..start]);
        out.push_str(to);
        last = start + part.len();
        done += 1;
    }
    out.push_str(&s[last..]);
    Some(out)
}

