def tail(nbytes=65536):
    sz=os.path.getsize(p)
    with open(p,'rb') as fh:
        fh.seek(max(0,sz-nbytes)); buf=fh.read()
    lines=buf.decode('utf-8','replace').split("\n")
    for line in reversed(lines):
        if '"model"' not in line: continue
        try: ev=json.loads(line)
        except: continue
        m=ev.get("message")
        if isinstance(m,dict) and m.get("model"): return m["model"]
    return None
for name,fn in (("full",full),("tail64k",tail)):
    t=time.perf_counter(); v=None
    for _ in range(20): v=fn()
    print("%-8s %6.2f ms  -> %r" % (name,(time.perf_counter()-t)/20*1000, v))
