helper = '''/// `py_space` for a single byte, for the all-ASCII scan below.
///
/// The ASCII half of Python's whitespace set exactly: space, `\\t\\n\\v\\f\\r`, and
/// the four C0 separators. NOT `u8::is_ascii_whitespace`, which omits `\\x0b`
/// and knows nothing about `\\x1c`–`\\x1f`.
#[inline]
fn is_py_space_ascii(b: u8) -> bool {
    matches!(b, b' ' | 0x09..=0x0d | 0x1c..=0x1f)
}

/// A one-byte ASCII needle, or `None` for anything else.'''
anchor = "/// A one-byte ASCII needle, or `None` for anything else."
assert t.count(anchor) == 1
t = t.replace(anchor, helper)

old = '''                        v = s.split(py_space)
                            .filter(|x| !x.is_empty())
                            .map(|x| Value::Str(x.into()))
                            .collect();'''
new = '''                        // `s.split(py_space)` decodes every character to test
                        // the predicate: callgrind on `'a b c d e f g h'.split()`
                        // put `Map::next` plus `str::validations` at 7.8% of the
                        // run, decoding UTF-8 to look for a space.
                        //
                        // A string with no byte >= 0x80 has no non-ASCII
                        // character in it at all, so on that string a byte scan
                        // is not an approximation of the character scan, it is
                        // the same scan. Anything else keeps the general path —
                        // non-ASCII whitespace (U+00A0, U+2028) is real and a
                        // byte scan would walk straight past it.
                        if s.is_ascii() {
                            let b = s.as_bytes();
                            let mut i = 0usize;
                            while i < b.len() {
                                while i < b.len() && is_py_space_ascii(b[i]) {
                                    i += 1;
                                }
                                let start = i;
                                while i < b.len() && !is_py_space_ascii(b[i]) {
                                    i += 1;
