TOK = ["a"," ","#","#c\n","\\ ","\\#","\\\\","[ab]","[a b]","[^ ]","[#]","[\\]]","(",")","(?:","|","*","+","?",".","\\d","{2}","{2, 3}","{","}","^","$","\\","\\\n","b","1"]
SUBJS = ["", "a", "ab", "a b", "a#b", "a1 b22", "aab", "x y", "a\nb", "a{2}", "ab ab", "  ", "\t\n", "abc123", "a-b_c"]
random.seed(99); bad=0; pairs=0; accept=0; acc_ex=[]
for _ in range(120000):
    p = "".join(random.choice(TOK) for _ in range(random.randint(1,6)))
    try: cp = re.compile(p, re.X); cpok=True
    except Exception: cpok=False
    try: rw = SV(p); cr = re.compile(rw); rwok=True
    except Exception: rwok=False; rw=None
    if cpok != rwok:
        if cpok:
            bad += 1
            if bad<8: print("REWRITE-REJECTS", repr(p), "->", repr(rw))
        else:
            accept += 1
            if len(acc_ex)<8: acc_ex.append((p,rw))
        continue
    if not cpok: continue
    pairs += 1
    for s in SUBJS:
        if cp.findall(s) != cr.findall(s):
            bad += 1
            if bad<8: print("BAD", repr(p), "->", repr(rw), repr(s), cp.findall(s), cr.findall(s))
            break
print("pairs:", pairs, "bad:", bad, "accepts-cpython-rejects:", accept)
for a in acc_ex: print("  ACC", repr(a[0]), "->", repr(a[1]))

