BITOPS=(ast.BitAnd, ast.BitOr, ast.BitXor)
parsed=0; unparsed=0
uses=[]        # any bitwise &,|,^ on non-set-looking operands
boolish=[]     # at least one operand statically bool-valued
both_bool=[]   # BOTH operands statically bool-valued -> real hit

def is_boolish(n):
    if isinstance(n, ast.Constant) and isinstance(n.value, bool): return True
    if isinstance(n, ast.Compare): return True
    if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.Not): return True
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in ('bool','any','all','isinstance','callable','hasattr'): return True
    if isinstance(n, ast.BinOp) and isinstance(n.op, BITOPS):
        return is_boolish(n.left) and is_boolish(n.right)
    return False

for e in d:
    p=e.get('program') or ''
    try:
        t=ast.parse(p); parsed+=1
    except SyntaxError:
        unparsed+=1; continue
    hit=False; bh=False; bb=False
    for n in ast.walk(t):
        if isinstance(n, ast.BinOp) and isinstance(n.op, BITOPS):
            hit=True
            l,r=is_boolish(n.left), is_boolish(n.right)
            if l or r: bh=True
            if l and r: bb=True
        elif isinstance(n, ast.AugAssign) and isinstance(n.op, BITOPS):
            hit=True
            if is_boolish(n.value): bh=True
    if hit: uses.append(e['id'])
    if bh: boolish.append(e['id'])
    if bb: both_bool.append((e['id'], p))

