import binascii as _b
def _mp_a2b(data):
    shift=0; nbits=0; hadpad=False; out=bytearray()
    A=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for ch in bytes(data):
        if ch==0x3D:
            if nbits==2 or (nbits==4 and hadpad): nbits=0; break
            hadpad=True
        i=A.find(bytes([ch]))
        if i<0: continue
        hadpad=False; shift=(shift<<6)|i; nbits+=6
        if nbits>=8: nbits-=8; out.append((shift>>nbits)&0xFF)
    if nbits: raise ValueError("incorrect padding")
    return bytes(out)
mp=type(sys)("binascii"); mp.a2b_base64=_mp_a2b
