def has_multi_set_display(src):
    """Program constructs a set with >1 element AND prints/iterates it."""
    try:
        t=ast.parse(src)
    except SyntaxError:
        return False
    sets=[]
    for n in ast.walk(t):
        if isinstance(n, ast.Set) and len(n.elts)>1:
            sets.append(n)
        if isinstance(n, ast.SetComp):
            sets.append(n)
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id=='set':
            sets.append(n)
        # set ops that yield sets
    return bool(sets)

