/// subject in it was either ASCII or whitespace: there was no non-space
/// multi-byte character anywhere. Returning the width makes the mistake
/// unrepresentable — every advance is by a whole unit.
type Unit = (bool, usize);

fn split_ws_ranges(
    len: usize,
    at: impl Fn(usize) -> Unit,
    before: impl Fn(usize) -> Unit,
    maxsplit: i64,
    from_right: bool,
) -> Vec<(usize, usize)> {
    let mut out: Vec<(usize, usize)> = Vec::new();
    if !from_right {
        let mut i = 0usize;
        while i < len {
            let (sp, w) = at(i);
            if !sp {
                break;
            }
            i += w;
        }
        let mut splits = 0i64;
        while i < len {
            if maxsplit >= 0 && splits >= maxsplit {
                out.push((i, len));
                return out;
            }
            let start = i;
            while i < len {
                let (sp, w) = at(i);
                if sp {
                    break;
                }
                i += w;
            }
            out.push((start, i));
            splits += 1;
            while i < len {
                let (sp, w) = at(i);
                if !sp {
                    break;
                }
                i += w;
            }
        }
        return out;
    }
    let mut j = len;
    while j > 0 {
        let (sp, w) = before(j);
        if !sp {
            break;
        }
        j -= w;
    }
    let mut splits = 0i64;
    while j > 0 {
        if maxsplit >= 0 && splits >= maxsplit {
            out.push((0, j));
            break;
        }
        let end = j;
