import subprocess, time
def t(cmd,n=25):
    best=1e9
    for _ in range(n):
        s=time.perf_counter_ns(); subprocess.run(cmd,capture_output=True); d=time.perf_counter_ns()-s
        if d<best: best=d
    return best/1e6
