fn is_word(c: char) -> bool { c.is_alphanumeric() || c == '_' }

struct M<'a> {
    text: &'a [char],
    flags: Flags,
    caps: Vec<Option<(usize, usize)>>,
    steps: u32,
}

impl<'a> M<'a> {
    fn eq(&self, a: char, b: char) -> bool {
        if self.flags.i { a.eq_ignore_ascii_case(&b) || a.to_lowercase().eq(b.to_lowercase()) } else { a == b }
    }
    fn class_hit(&self, ranges: &[(char, char)], neg: bool, c: char) -> bool {
        let mut hit = ranges.iter().any(|(lo, hi)| c >= *lo && c <= *hi);
        if !hit && self.flags.i {
            let lc = c.to_ascii_lowercase();
            let uc = c.to_ascii_uppercase();
            hit = ranges.iter().any(|(lo, hi)| (lc >= *lo && lc <= *hi) || (uc >= *lo && uc <= *hi));
        }
        hit != neg
    }
    fn m(&mut self, node: &Node, at: usize, k: &mut dyn FnMut(&mut M<'a>, usize) -> bool) -> bool {
        self.steps += 1;
        if self.steps > 2_000_000 { return false; }
        match node {
            Node::Empty => k(self, at),
            Node::Char(c) => match self.text.get(at) {
                Some(t) if self.eq(*c, *t) => k(self, at + 1),
                _ => false,
            },
            Node::Any => match self.text.get(at) {
                Some(t) if self.flags.s || *t != '\n' => k(self, at + 1),
                _ => false,
            },
            Node::Class { ranges, neg } => match self.text.get(at) {
                Some(t) if self.class_hit(ranges, *neg, *t) => k(self, at + 1),
                _ => false,
            },
            Node::Start => {
                let ok = at == 0 || (self.flags.m && self.text.get(at - 1) == Some(&'\n'));
                ok && k(self, at)
            }
            Node::End => {
                let ok = at == self.text.len() || (self.flags.m && self.text.get(at) == Some(&'\n'))
                    || (at + 1 == self.text.len() && self.text.get(at) == Some(&'\n'));
                ok && k(self, at)
            }
            Node::WordB | Node::NotWordB => {
                let before = at > 0 && is_word(self.text[at - 1]);
                let after = at < self.text.len() && is_word(self.text[at]);
                let b = before != after;
                let want = matches!(node, Node::WordB);
                (b == want) && k(self, at)
            }
            Node::Backref(n) => {
                let Some(Some((s0, e0))) = self.caps.get(*n).copied() else { return false };
                let len = e0 - s0;
                if at + len > self.text.len() { return false; }
                for i in 0..len {
                    if !self.eq(self.text[s0 + i], self.text[at + i]) { return false; }
