                let saved = self.caps.get(idx).copied().flatten();
                let start = at;
                let ok = self.m(inner, at, &mut |me: &mut M<'a>, end: usize| {
                    let prev = me.caps[idx];
                    me.caps[idx] = Some((start, end));
                    if k(me, end) { true } else { me.caps[idx] = prev; false }
                });
                if !ok { if idx < self.caps.len() { self.caps[idx] = saved; } }
                ok
