            Node::Alt(branches) => {
                for b in branches {
                    if self.m(b, at, k) { return true; }
                }
                false
            }
            Node::Seq(items) => self.seq_from(items, 0, at, k),
            Node::Rep { inner, min, max, greedy } => self.rep(inner, *min, *max, *greedy, 0, at, k),
        }
    }
    fn seq_from(&mut self, items: &[Node], i: usize, at: usize, k: &mut dyn FnMut(&mut M<'a>, usize) -> bool) -> bool {
        if i == items.len() { return k(self, at); }
        let (head, rest) = (&items[i], items);
