                "findall" => {
                    let mut out: Vec<Value> = Vec::new();
                    let mut at = 0;
                    while let Some((a, b, caps)) = search_at(&rx, &text, at) {
                        out.push(if rx.ngroups == 0 {
                            Value::Str(sub(a, b).into())
                        } else if rx.ngroups == 1 {
                            match caps[1] { Some((x, y)) => Value::Str(sub(x, y).into()), None => Value::Str("".into()) }
                        } else {
                            Value::Tuple(Rc::new(caps[1..].iter().map(|g| match g {
                                Some((x, y)) => Value::Str(sub(*x, *y).into()), None => Value::Str("".into()) }).collect()))
                        });
                        at = if b > a { b } else { b + 1 };
                        if at > text.len() { break; }
                    }
                    list(out)
                }
                "split" => {
                    let mut out: Vec<Value> = Vec::new();
                    let mut at = 0;
                    let mut last = 0;
                    while let Some((a, b, caps)) = search_at(&rx, &text, at) {
                        if b == a { at = a + 1; if at > text.len() { break; } continue; }
                        out.push(Value::Str(sub(last, a).into()));
                        for g in caps.iter().skip(1) {
                            out.push(match g { Some((x, y)) => Value::Str(sub(*x, *y).into()), None => Value::None });
                        }
                        last = b;
                        at = b;
                    }
                    out.push(Value::Str(sub(last, text.len()).into()));
                    list(out)
                }
                "sub" | "subn" => {
                    let repl = args.get(1).cloned().ok_or_else(|| type_err("missing replacement"))?;
                    if !matches!(repl, Value::Str(_)) {
                        return Err(unsupported("regex", "a callable replacement in re.sub()"));
                    }
                    let tpl = fmt::to_str(&repl)?;
                    let mut out = String::new();
                    let mut at = 0;
                    let mut last = 0;
                    let mut n = 0i64;
                    while let Some((a, b, caps)) = search_at(&rx, &text, at) {
                        out.push_str(&sub(last, a));
                        out.push_str(&expand_template(&tpl, &text, &caps)?);
                        n += 1;
                        last = b;
                        at = if b > a { b } else {
                            if b < text.len() { out.push(text[b]); }
                            b + 1
                        };
                        if at > text.len() { break; }
                        last = last.max(at.min(text.len()));
                    }
                    out.push_str(&sub(last.min(text.len()), text.len()));
                    if name == "subn" { Value::Tuple(Rc::new(vec![Value::Str(out.into()), Value::Int(n)])) }
                    else { Value::Str(out.into()) }
                }
