            if a.stdout != b.stdout: diffs.append((e,a.stdout.strip(),b.stdout.strip()))
            else: ok+=1
    print("### %s: %d exprs, ok=%d refused=%d cpy_err=%d MISMATCH=%d rcdiff=%d" % (label,len(exprs),ok,refused,cerr,len(diffs),len(rcd)))
