import subprocess, sys, os, json
LYP="/root/.lypning/bin/lypning"; CPY="/usr/bin/python3"
EXCS=["TypeError","ValueError","StopIteration","IndexError","KeyError","AttributeError","ZeroDivisionError","OverflowError","NameError","RecursionError"]

def prog(exprs):
    out=[]
    for i,e in exprs:
        out.append("try:")
        out.append("    _r = %s" % e)
        out.append('    print(%d, "OK", repr(_r))' % i)
        for x in EXCS:
            out.append("except %s as _e:" % x)
            out.append('    print(%d, "%s", _e)' % (i, x))
        out.append("except Exception as _e:")
        out.append('    print(%d, "Other", _e)' % i)
    return "\n".join(out)+"\n"

def run(binpath, src, tag):
    f=os.path.abspath("chunk_%s.py"%tag)
    open(f,"w").write(src)
    p=subprocess.run([binpath,f],capture_output=True,text=True,timeout=120)
    return p.returncode,p.stdout,p.stderr

def parse(out):
    d={}
    for line in out.splitlines():
        parts=line.split(" ",2)
        if len(parts)>=2 and parts[0].isdigit():
            d[int(parts[0])]=line.split(" ",1)[1]
    return d

def sweep(exprs, name):
    # exprs: list of strings
    items=list(enumerate(exprs))
    diffs=[]; refused=[]; errors=[]
    def go(batch, depth=0):
        if not batch: return
        src=prog(batch)
        rc,so,se=run(LYP,src,name)
        if rc==90:
            if len(batch)==1:
                refused.append((batch[0][0], se.strip().splitlines()[-1] if se.strip() else ""))
                return
            m=len(batch)//2
            go(batch[:m],depth+1); go(batch[m:],depth+1); return
        if rc!=0:
            if len(batch)==1:
                errors.append((batch[0][0],"LYP_EXIT_%d"%rc, (se.strip().splitlines() or [""])[-1]))
                return
            m=len(batch)//2
            go(batch[:m],depth+1); go(batch[m:],depth+1); return
        rc2,so2,se2=run(CPY,src,name+"c")
        a=parse(so); b=parse(so2)
        for i,e in batch:
            if a.get(i)!=b.get(i):
                diffs.append((i,e,a.get(i),b.get(i)))
    B=30
    for k in range(0,len(items),B):
        go(items[k:k+B])
    return diffs,refused,errors

