def const_eval(node):
    try:
        return ast.literal_eval(node)
    except Exception:
        # handle a ** b of literals
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Pow):
            try:
                l = ast.literal_eval(node.left); r = ast.literal_eval(node.right)
                if isinstance(l,int) and isinstance(r,int) and 0<=r<10000:
                    return l**r
            except Exception:
                return None
        return None

